# Generated by Django 5.2.17 on 2026-09-19 00:03

from django.db import migrations

# 旧状态 -> 新审批流状态
STATUS_MAPPING = {
    "pending": "pending_region_admin",
    "approved": "approved",
    "rejected": "draft",
    "dispatched": "approved",
    "in_progress": "accepting",
    "completed": "accepting",
    "settled": "settled",
}


def migrate_status_and_codes(apps, schema_editor):
    RepairRequest = apps.get_model("approvals", "RepairRequest")

    # 1) 状态值映射
    for old_status, new_status in STATUS_MAPPING.items():
        RepairRequest.objects.filter(status=old_status).update(status=new_status)

    # 2) 旧编号（WX-xxxx 等不符合新规则）按“油站编码+年月+序号”重排
    for repair in RepairRequest.objects.select_related("site").order_by("site_id", "created_at", "id"):
        prefix = f"{repair.site.code}{repair.created_at.strftime('%Y%m')}"
        sequence = (
            RepairRequest.objects.filter(
                site_id=repair.site_id, code__startswith=prefix
            ).count()
            + 1
        )
        repair.code = f"{prefix}{sequence:03d}"
        repair.save()


class Migration(migrations.Migration):

    dependencies = [
        ('approvals', '0008_repairrequest_parent_alter_material_material_type_and_more'),
    ]

    operations = [
        migrations.RunPython(migrate_status_and_codes, migrations.RunPython.noop),
    ]
